SET DEFINE OFF
-- Synthetic source database for the retail demo (Sales performance data product)
-- Dialect: oracle. Generated by ADEF; all values are synthetic.

-- Schema-only accounts: they own the tables and cannot log in (no passwords).
CREATE USER CRM NO AUTHENTICATION QUOTA UNLIMITED ON USERS;
CREATE USER PIM NO AUTHENTICATION QUOTA UNLIMITED ON USERS;
CREATE USER POS NO AUTHENTICATION QUOTA UNLIMITED ON USERS;

-- Stores
CREATE TABLE POS.STORE (
    STORE_ID                   VARCHAR2(10)       NOT NULL,
    STORE_NAME                 VARCHAR2(100)     ,
    REGION                     VARCHAR2(20)      ,
    FORMAT                     VARCHAR2(12)      ,
    LAST_UPDATED_TS            TIMESTAMP         ,
    CONSTRAINT PK_STORE PRIMARY KEY (STORE_ID)
);

COMMENT ON COLUMN POS.STORE.LAST_UPDATED_TS IS 'Row last changed (CDC watermark)';

-- Products
CREATE TABLE PIM.PRODUCT (
    PRODUCT_ID                 VARCHAR2(14)       NOT NULL,
    PRODUCT_NAME               VARCHAR2(200)     ,
    CATEGORY                   VARCHAR2(40)      ,
    BRAND                      VARCHAR2(40)      ,
    LIST_PRICE                 NUMBER(10,2)      ,
    UNIT_COST                  NUMBER(10,2)      ,
    LAST_UPDATED_TS            TIMESTAMP         ,
    CONSTRAINT PK_PRODUCT PRIMARY KEY (PRODUCT_ID)
);

COMMENT ON COLUMN PIM.PRODUCT.LAST_UPDATED_TS IS 'Row last changed (CDC watermark)';

-- Loyalty customers
CREATE TABLE CRM.CUSTOMER (
    CUSTOMER_ID                VARCHAR2(20)       NOT NULL,
    EMAIL                      VARCHAR2(200)     ,
    LOYALTY_TIER               VARCHAR2(10)      ,
    CONSENT_MARKETING          NUMBER(1)         ,
    LAST_UPDATED_TS            TIMESTAMP         ,
    CONSTRAINT PK_CUSTOMER PRIMARY KEY (CUSTOMER_ID)
);

COMMENT ON COLUMN CRM.CUSTOMER.LAST_UPDATED_TS IS 'Row last changed (CDC watermark)';

-- Sales lines
CREATE TABLE POS.ORDER_LINE (
    ORDER_LINE_ID              VARCHAR2(24)       NOT NULL,
    ORDER_ID                   VARCHAR2(20)      ,
    STORE_ID                   VARCHAR2(10)      ,
    PRODUCT_ID                 VARCHAR2(14)      ,
    CUSTOMER_ID                VARCHAR2(20)      ,
    ORDER_TS                   TIMESTAMP         ,
    QUANTITY                   NUMBER(10)        ,
    GROSS_AMOUNT               NUMBER(12,2)      ,
    DISCOUNT_AMOUNT            NUMBER(12,2)      ,
    RETURN_FLAG                VARCHAR2(1)       ,
    LAST_UPDATED_TS            TIMESTAMP         ,
    CONSTRAINT PK_ORDER_LINE PRIMARY KEY (ORDER_LINE_ID)
);

COMMENT ON COLUMN POS.ORDER_LINE.LAST_UPDATED_TS IS 'Row last changed (CDC watermark)';
